// Practice question bank (EN): 8 per topic, each with difficulty 1 — easy, 2 — medium, 3 — hard.
// Mirrors testsData.js (same ids, correct answers and difficulty). See testsData.js for details.
const testsDataEN = {
  1: [
    { "id": 1, "difficulty": 2, "question": "A website displays HTTPS and a padlock in the address bar. What does this guarantee?", "options": ["The site is verified and definitely not fraudulent", "The site doesn't collect or share any user data", "Data is encrypted, but the site's honesty isn't guaranteed", "The site passed checks by an antivirus company and the browser"], "correct": 2, "explanation": "HTTPS only guarantees an encrypted channel: others on the network can't read or alter the data in transit. But the site itself can be a phishing site — certificates are free and take minutes to get, so most fraudulent sites use HTTPS too. The padlock means a secure connection, not an honest owner." },
    { "id": 2, "difficulty": 1, "question": "A friend sent you a sensational headline: 'Proven: GMOs cause cancer!' with a link to health-truth24.ru. What do you do FIRST?", "options": ["Share it in the chat: my friend usually checks what they send", "Check whether the site has HTTPS and a neat design", "See how many times the story has been shared and liked", "Find the primary source: was such a study published in a journal?"], "correct": 3, "explanation": "Share counts and trust in the sender are poor indicators of truth. An MIT study (Vosoughi et al., Science, 2018) found that false news on Twitter spread faster and farther than true news. Look for the primary source — a peer-reviewed paper (PubMed, The Lancet, Nature). An unknown domain with numbers in its name is a red flag." },
    { "id": 3, "difficulty": 1, "question": "Which of the following is NOT part of your digital footprint?", "options": ["Your laptop's CPU serial number", "Your Google search history", "A geotagged photo posted on Instagram", "A comment you deleted a year ago"], "correct": 0, "explanation": "Your CPU serial number is never automatically published. Everything else is part of your digital footprint: searches are stored by Google, geotags are embedded in photo EXIF data, and deleted comments are often cached on Wayback Machine or in screenshots." },
    { "id": 4, "difficulty": 2, "question": "You discover a flashlight app on Android requesting access to contacts, microphone, and location. What principle does this violate?", "options": ["Zero Trust principle", "Data Minimization principle", "Defense in Depth principle", "Least Privilege principle"], "correct": 1, "explanation": "Data minimization requires collecting only what is strictly necessary for the service's function. A flashlight only needs access to the camera flash. Requesting contacts, microphone, and location is excessive data collection, often monetized through ad networks." },
    { "id": 5, "difficulty": 1, "question": "About 60% of data breaches involve the human element (Verizon DBIR, 2025). What conclusion is most accurate?", "options": ["Technical tools are useless — only people matter", "Training people is needed alongside technical measures, not instead", "With trained users, antivirus and firewalls are no longer needed", "The human factor can be fully removed through automation"], "correct": 1, "explanation": "The statistic highlights the importance of the human factor, not the uselessness of technology. The correct conclusion: protection must be multi-layered (defense in depth). Training alone without technology, or technology alone without training, is incomplete. Automation reduces risk but doesn't eliminate it." },
    { "id": 6, "difficulty": 3, "question": "You're checking a photo 'from the scene' that is spreading in group chats. What best shows the picture is old or from another place?", "options": ["A reverse image search (Google Lens, TinEye, Yandex)", "How many people have already forwarded it in chats", "A watermark of a well-known news channel on the photo", "Blurry areas that appear when you zoom in a lot"], "correct": 0, "explanation": "A reverse image search finds earlier publications of the same picture — this is how old photos passed off as new are most often exposed. Forward counts prove nothing, watermarks are easy to fake, and real photos can be blurry too. Tools: Google Lens, TinEye, Yandex Images; for video — InVID." },
    { "id": 7, "difficulty": 3, "question": "A Telegram channel posted a screenshot of a 'letter from the ministry'. What most strongly suggests it's fake?", "options": ["The screenshot shows no stamp or signature at the bottom", "The letter isn't on the ministry's site or official channels", "The channel that posted it has a lot of subscribers", "The text has bureaucratic wording and order numbers"], "correct": 1, "explanation": "A screenshot is easy to fabricate, and stamps, signatures and official style can be faked in an editor in minutes. The reliable check is to find the document in an official source: the agency's website, its verified accounts, legal databases (in Kazakhstan — adilet.zan.kz). Without official confirmation, don't trust or spread it." },
    { "id": 8, "difficulty": 3, "question": "Why can social media algorithms create a 'filter bubble'?", "options": ["They deliberately hide all news from official media", "They show every user exactly the same feed", "They show more of what you've already liked and watched", "They delete posts that get only a few likes"], "correct": 2, "explanation": "Recommendation algorithms optimize engagement: the more you like and watch certain topics and opinions, the more similar content you get. Your feed narrows to familiar views, and other perspectives become almost invisible. It helps to deliberately follow diverse sources and check important news outside the feed." },
  ],
  2: [
    { "id": 1, "difficulty": 2, "question": "After registration, a site emails you your password in plain text. What does this mean?", "options": ["The site stores your password readably — a serious flaw", "The site uses strong encryption, since it could send it", "It's common practice so users don't forget their password", "It doesn't matter if two-factor authentication is enabled"], "correct": 0, "explanation": "If a site can send you your password, it's stored in readable form (plaintext or reversible encryption). The correct practice: store only password hashes (bcrypt, Argon2). In a breach, all passwords on such a site end up with attackers. Change that password immediately and never reuse it." },
    { "id": 2, "difficulty": 2, "question": "Which of these passwords has the greatest entropy (hardest to brute-force)?", "options": ["P@ssw0rd!2024", "qK#9mX$vL2@nW", "correct-horse-battery-staple-2024", "My_Very_Long_Password_2024!"], "correct": 2, "explanation": "A passphrase of random words is strong because of its length (33 characters). qK#9mX… looks complex but is short. P@ssw0rd is a predictable letter substitution (leet speak) that every cracking dictionary already contains. Length matters more than individual character 'complexity': every extra character multiplies the number of possible combinations." },
    { "id": 3, "difficulty": 3, "question": "A colleague says: 'I use SMS 2FA, so my password doesn't matter — I can use a simple one.' Is he right?", "options": ["Yes — the second factor fully covers a weak password", "Partly — with biometrics enabled, the password doesn't matter", "No — SMS can be intercepted, so a weak password is still a risk", "Yes — with 2FA on, the password is just a formality"], "correct": 2, "explanation": "SMS 2FA has vulnerabilities: SIM swapping (an attacker ports your number to their SIM), SS7 protocol attacks on carrier networks, SMS interception via malware. A weak password makes the first factor easier to attack. The ideal: strong password + hardware key (YubiKey) or TOTP app (Google Authenticator) instead of SMS." },
    { "id": 4, "difficulty": 2, "question": "You've forgotten your password manager's master password. What happens?", "options": ["Support will reset it via a link sent to your email", "Access to the vault will most likely be lost for good", "You can recover it with your phone's fingerprint sensor", "You can export the passwords to a backup without it"], "correct": 1, "explanation": "Good password managers (Bitwarden, 1Password) use zero-knowledge architecture: they don't know your master password. Decryption happens only on the user's device. This means nobody — including support — can recover access. Write your master password on paper and store it in a safe physical location." },
    { "id": 5, "difficulty": 3, "question": "Which type of two-factor authentication is most resistant to phishing?", "options": ["A code sent to your phone by SMS", "A hardware key (FIDO2/WebAuthn)", "A code from Google Authenticator", "A confirmation code sent by email"], "correct": 1, "explanation": "FIDO2/WebAuthn — hardware keys (YubiKey, Titan) and passkeys — uses public-key cryptography bound to a specific domain. On a phishing site the key simply won't work because the domain doesn't match. SMS and email codes can be intercepted, and a victim can type an app-based TOTP code into a fake site, where the attacker uses it in real time." },
    { "id": 6, "difficulty": 1, "question": "Which password is the strongest for your email?", "options": ["Aigerim_Almaty_2005_Birthday", "12345678Qq!", "Qwerty!2024Qwerty!2024", "summer-coffee-hill-tram-42"], "correct": 3, "explanation": "A password made of several random words is long and still memorable. A name, city and birth year can be guessed from social media even if the password is long. '12345678Qq!' and 'Qwerty' are at the top of every cracking dictionary, and repeating them adds no strength. What matters is length, randomness and uniqueness for each site." },
    { "id": 7, "difficulty": 1, "question": "Where is it safest to store many different passwords?", "options": ["In phone notes, with a separate note for each site", "In a password manager with a strong master password", "On a sticky note under the keyboard at the office", "In a saved chat with yourself in your messenger app"], "correct": 1, "explanation": "A password manager (Bitwarden, 1Password, KeePassXC or the one built into your browser or OS) stores passwords encrypted and helps keep them unique. Notes and chats aren't separately encrypted: if your phone or messenger account is stolen, every password goes with it. Anyone near your desk can read a sticky note." },
    { "id": 8, "difficulty": 3, "question": "After a database leak, why are passwords hashed with a 'salt' harder to crack?", "options": ["The salt encrypts the whole database so it can't be read", "The salt removes weak passwords at registration", "Same passwords give different hashes, so tables don't work", "The salt makes passwords longer and easier to remember"], "correct": 2, "explanation": "A salt is a random string added to each user's password before hashing. So two people with the password '123456' get different hashes, and precomputed 'rainbow tables' become useless: each hash must be cracked separately. Combined with slow algorithms (bcrypt, Argon2) this greatly slows cracking, though a weak password is still found faster than a strong one." },
  ],
  3: [
    { "id": 1, "difficulty": 1, "question": "You receive an email from 'security@google.com' about suspicious activity. The address looks exactly correct. What do you check FIRST?", "options": ["Click 'Review activity', since the domain in the email is right", "Check that the link in the email starts with https://", "Reply to the email and ask them to confirm it's Google", "Open Google yourself in the browser and check activity there"], "correct": 3, "explanation": "Sender addresses can be spoofed (email spoofing). The safe approach: don't click links in the email — open the site manually. Legitimate Google security notifications will also appear at accounts.google.com. Replying to the attacker only confirms your account is active." },
    { "id": 2, "difficulty": 1, "question": "How does spear phishing fundamentally differ from regular phishing?", "options": ["It targets a specific person and uses their personal data", "It only uses voice calls rather than email messages", "It only attacks corporate networks, not ordinary people", "It is technically harder because it requires hacking a server"], "correct": 0, "explanation": "Spear phishing is a personalized attack. The attacker studies the victim in advance: colleagues' names, projects, writing style, bank. The email contains real details ('Hi Aigul, I need your signature for the Almaty_Q4 project…'), which makes it convincing. A similar scheme impersonating employees cost Ubiquiti $46.7 million." },
    { "id": 3, "difficulty": 2, "question": "What is 'pretexting' in social engineering?", "options": ["Creating a fake site with a very similar domain name", "Inventing a cover story and a role to win trust", "Sending identical mass emails without personalization", "Scanning systems for vulnerabilities before an attack"], "correct": 1, "explanation": "Pretexting is the creation of a scenario (pretext): 'I'm from IT support, I need your password to update the system' or 'I'm a bank auditor, tell me the last 4 digits of your card.' The attacker creates a plausible role and situation that lowers the victim's guard. This is a purely psychological attack requiring no technical tools." },
    { "id": 4, "difficulty": 1, "question": "You receive an email with an attachment named 'Report_Q3_2024.pdf.exe'. What has happened?", "options": ["It's a corrupted PDF — open it and save it again", "Windows will block such a file from an email by itself", "It's a program disguised as a PDF with a double extension", "The file is safe if someone you know sent it"], "correct": 2, "explanation": "A double extension (.pdf.exe) is a classic trick. Windows hides known extensions by default, so the user sees 'Report_Q3_2024.pdf' and thinks it's a document. In reality it runs a program. Email services often block .exe attachments, so attackers hide such files inside archives. Never run programs from emails — even from people you know, as their mailbox may be compromised." },
    { "id": 5, "difficulty": 2, "question": "What is typosquatting and why is it dangerous?", "options": ["Stealing passwords by intercepting DNS requests", "Injecting code into a real site via SQL injection", "Stealing passwords from browser autofill", "Registering typo domains like goggle.com"], "correct": 3, "explanation": "Typosquatting: fraudsters register 'goggle.com', 'amaz0n.com', 'app1e.com' — domains users land on when they mistype. The site looks identical to the original and collects credentials. The risk increases on mobile devices where small fonts make URL verification harder. Always use bookmarks for critical sites." },
    { "id": 6, "difficulty": 3, "question": "'Bank security' calls you: the bank's number is on screen, they know your name and the last digits of your card. They ask for the SMS code to 'cancel a transaction'. What's right?", "options": ["Since the number and data match, you can tell them the code", "You can tell the code if the caller gives their surname", "First ask the caller to read out your full card number", "Numbers are spoofed and data comes from leaks — don't share it"], "correct": 3, "explanation": "Caller ID can be spoofed, and fraudsters get names and card digits from leaked databases. A real bank never asks you to read out an SMS code — that code confirms a transfer or a login. The right move: hang up and call the number on the back of your card or in the bank's app yourself." },
    { "id": 7, "difficulty": 3, "question": "A page looks like Google sign-in, the address starts with https://, and the address bar shows accounts.google.com.login-secure.app. Who owns the site?", "options": ["Google: the address contains accounts.google.com", "Whoever owns the domain login-secure.app", "Google: it has HTTPS and the familiar design", "secure.app, a Google partner company"], "correct": 1, "explanation": "The site owner is determined by the end of the address before the first '/': here it's login-secure.app. Everything to the left (accounts.google.com.) is just subdomains the owner can name however they like. HTTPS and a familiar design guarantee nothing: certificates are free and sign-in pages are copied in minutes." },
    { "id": 8, "difficulty": 3, "question": "A 'friend' messages you from a new number: 'This is my new number, urgently send me 20,000, I'll pay you back tonight'. What do you do?", "options": ["Send it: they know your name and write in their usual style", "Contact your friend on their old number or in person", "Ask them to send a photo to prove it's really them", "Send half the amount to reduce the risk of losing it"], "correct": 1, "explanation": "This is the classic 'friend in trouble' scam. Names and writing style are easy to learn from social media, and photos can be taken from there too. Verify through another channel the scammer doesn't control: a call to the old number, a question only the two of you can answer, or a mutual friend." },
  ],
  4: [
    { "id": 1, "difficulty": 2, "question": "An attacker wants to target you via social media OSINT. Which combination of data from public sources is most valuable?", "options": ["Name and favourite movie from a VK profile", "Follower count and a list of public likes", "Name, employer, bank and birth date from various posts", "Profile picture and username across several networks"], "correct": 2, "explanation": "The attacker needs a data combination for social engineering: knowing your name, bank, and date of birth, they can call the bank, impersonate you, and request account changes. LinkedIn gives title and company, Instagram gives bank (card photos, office interior), Facebook gives date of birth. This is how loans are taken out in someone else's name." },
    { "id": 2, "difficulty": 3, "question": "You signed into a new app via 'Continue with Facebook'. What happened from a security perspective?", "options": ["Facebook gave the app your password in encrypted form", "Nothing — this kind of sign-in is always safer than a password", "An isolated account was created, unrelated to Facebook", "The app got a token and access to part of your profile data"], "correct": 3, "explanation": "OAuth doesn't transfer your password, but issues an access token for profile data. The scope of data depends on requested permissions: name and email is the minimum, contacts and posts is the maximum. If the app is breached, the attacker gets this token. Additionally, compromising your Facebook account loses access to all services authenticated through it." },
    { "id": 3, "difficulty": 3, "question": "What is credential stuffing and how does it differ from brute-force?", "options": ["Stuffing tries leaked pairs; brute force tries all combinations", "They're the same: both automatically guess passwords", "Stuffing only attacks corporate systems, not individuals", "Brute force uses dictionaries; stuffing uses random strings"], "correct": 0, "explanation": "Credential stuffing takes databases of stolen logins and passwords and automatically tries them on other sites. It works because people reuse passwords: in a 2019 Google/Harris Poll survey, 65% used the same password for multiple or all accounts. Brute force tries every combination. Even if only 0.1–2% of pairs work, a million stolen records means thousands of hijacked accounts." },
    { "id": 4, "difficulty": 1, "question": "Which action IMMEDIATELY reduces your OSINT exposure on social media?", "options": ["Change your username to a pseudonym everywhere", "Make profiles private and remove excess personal data", "Delete every post that is older than one year", "Turn off location services in your phone settings"], "correct": 1, "explanation": "Changing your username doesn't help — all old posts with tags and mentions remain. Private mode restricts strangers' access to content. Removing your real name, employer, phone, and ID number from the public description eliminates key OSINT data. Turning off phone location doesn't affect already-published data." },
    { "id": 5, "difficulty": 2, "question": "You notice an unfamiliar device in Facebook's 'Active Sessions' section. What is the correct order of actions?", "options": ["Delete Facebook and create a new account right away", "Just change the password — that's already enough", "Wait: it's most likely one of your old devices", "Change password, end sessions, turn on 2FA"], "correct": 3, "explanation": "Both steps matter together. Changing the password stops the attacker from signing in again, and ending sessions kicks them out if they're already in: not every service closes existing sessions automatically after a password change. Then enable 2FA and check which apps have access to your account — the attacker may have connected their own app to keep access." },
    { "id": 6, "difficulty": 1, "question": "You posted a photo of your boarding pass in your stories. What on it can an attacker use?", "options": ["Nothing: it only shows your seat and departure time", "Only the airline's name, which isn't a secret anyway", "The barcode and booking code, which open your reservation", "Only the flight number, which is on the airport board anyway"], "correct": 2, "explanation": "A boarding pass barcode contains your name, booking reference (PNR) and flight details. With your surname and PNR, the airline's website often lets anyone open the booking: see your contacts, change or cancel the flight. Cover the barcode and booking code before posting — or better, post after the trip." },
    { "id": 7, "difficulty": 2, "question": "A stranger tagged you in a photo you've never seen before. Which setting helps you control this?", "options": ["Turning off notifications about new photo tags", "Changing your profile picture to one without a face", "Hiding your friends list from strangers", "Manually approving tags before they show on your profile"], "correct": 3, "explanation": "Instagram and Facebook let you turn on manual tag approval: photos of you won't appear on your profile until you approve them. Turning off notifications only hides the problem, and your profile picture or friends list doesn't affect other people's tags. This way you control which photos and places are linked to your name." },
    { "id": 8, "difficulty": 3, "question": "What's dangerous about quizzes like 'Find out who you are: name your first pet and childhood street'?", "options": ["These quizzes infect your phone with a virus as soon as they open", "These are common answers to password-reset security questions", "The quiz authors get access to your private messages", "The social network may block your account because of them"], "correct": 1, "explanation": "Your first pet, mother's maiden name and childhood street are typical 'security questions' for recovering email and bank accounts. Such quizzes collect these answers en masse. It's better not to answer them, and to give random answers to security questions and keep them in a password manager." },
  ],
  5: [
    { "id": 1, "difficulty": 2, "question": "How does a rootkit fundamentally differ from a regular virus?", "options": ["A rootkit encrypts files, while a virus deletes them", "A rootkit hides itself at the system level from defenses", "A rootkit only works on Linux-based systems", "A rootkit spreads only through USB flash drives"], "correct": 1, "explanation": "A rootkit embeds into the OS kernel or bootloader and conceals itself: hiding processes, files, and network connections from antivirus and the user. The system 'looks clean' but is infected. Detecting a rootkit with a standard antivirus is difficult — you need to boot from a clean medium or use specialized tools (Rootkit Revealer, GMER)." },
    { "id": 2, "difficulty": 1, "question": "Your computer is idle but the CPU is at 90–100% and the fan is running at maximum. What might this indicate?", "options": ["It's normal: Windows is always updating in the background", "Most likely the computer's hard drive has overheated", "The computer simply doesn't have enough RAM", "A cryptominer may be secretly running on it"], "correct": 3, "explanation": "Cryptominers (coinminers) are malware that secretly use the CPU/GPU to mine cryptocurrency. Symptoms: high idle load, overheating, slow performance. Check Task Manager for suspicious high-CPU processes. An antivirus scan and checking startup programs will help identify the threat." },
    { "id": 3, "difficulty": 2, "question": "Why might a standard backup not save you from ransomware?", "options": ["Ransomware always physically wipes every backup copy", "Antivirus software blocks restoring files from a backup", "A backup connected to the system gets encrypted too", "Backups keep documents but not system files"], "correct": 2, "explanation": "Modern ransomware scans and encrypts connected drives, network shares, and cloud storage with sync enabled. If an external drive is plugged in — it gets encrypted too. The 3-2-1 rule solves this: one copy must be offline (disconnected from the system) or in a cloud without direct sync. That's why backups must be kept isolated." },
    { "id": 4, "difficulty": 3, "question": "What is 'fileless malware' and why is it more dangerous than regular malware?", "options": ["Malware without an icon, detectable only by its size", "Malware that deletes itself after the first run", "Malware living in memory and system processes", "Malware that arrives in emails without attachments"], "correct": 2, "explanation": "Fileless malware executes in memory (PowerShell, WMI, registry) and creates no files on disk — a file-scanning antivirus won't detect it. It uses legitimate system tools (living-off-the-land). Evidence disappears after a reboot. Detection requires behavioral analysis and EDR solutions, not signature-based antivirus." },
    { "id": 5, "difficulty": 2, "question": "You opened a PDF from someone you know — nothing happened and the file looks normal. Should you be concerned?", "options": ["Yes — a PDF can silently exploit a flaw in the reader", "No — if the document opened normally, there's no threat", "No — PDF files cannot contain executable code", "Only if the PDF has macros, like Word files do"], "correct": 0, "explanation": "PDFs support JavaScript and embedded objects, and can exploit vulnerabilities in Adobe Reader or browser-based viewers. Malicious code can execute without any visible signs. If your contact's account was compromised, they may unknowingly be spreading malware. Suspicious PDFs should be checked on VirusTotal or opened in an isolated environment." },
    { "id": 6, "difficulty": 1, "question": "Where is it safest to install Android apps from?", "options": ["From a site linked in an Instagram ad", "From an APK file someone posted in a Telegram channel", "From Google Play, after checking the developer", "From anywhere, if you turn off Play Protect"], "correct": 2, "explanation": "Google Play checks and scans apps (Play Protect), though malware sometimes gets through — so check the developer, reviews and permissions. APKs from channels and ads are the main route for Android banking trojans: nobody has checked those files. Never turn off Play Protect to install something." },
    { "id": 7, "difficulty": 3, "question": "After installing a 'free cracked' Photoshop, your Telegram and Steam accounts were hijacked. What most likely happened?", "options": ["An infostealer in the installer took sessions and passwords", "Photoshop sent your saved passwords to Adobe by itself", "The accounts were brute-forced; the install is unrelated", "Antivirus deleted files and the accounts reset themselves"], "correct": 0, "explanation": "Cracked software is the main way infostealers (RedLine, Lumma, etc.) spread. In seconds they grab browser-saved passwords, session cookies and messenger files, so attackers get in even without the password or 2FA. What to do: clean or reinstall the system, end all sessions and change passwords from a clean device." },
    { "id": 8, "difficulty": 3, "question": "You found a USB stick labelled 'Salaries 2025' in the parking lot. Why is plugging it into a work computer dangerous, even with antivirus on?", "options": ["Sticks with someone else's files quickly damage USB ports", "It's only dangerous if the stick has files ending in .exe", "It may be a device that types commands like a keyboard", "Antivirus scans the stick right away, so it's not dangerous"], "correct": 2, "explanation": "Dropped USB sticks are a well-known attacker trick. Inside there may be not just a malicious file but a device like a Rubber Ducky: the computer sees it as a keyboard, and it 'types' commands in seconds that antivirus doesn't treat as a file. Hand a found stick to IT instead of checking it yourself." },
  ],
  6: [
    { "id": 1, "difficulty": 3, "question": "You visit your bank's website over public Wi-Fi and see HTTPS. Are you protected from a MITM attack?", "options": ["Yes — HTTPS fully protects against interception in a cafe", "Yes — banks always add their own encryption on top of HTTPS", "No — HTTPS doesn't protect against man-in-the-middle at all", "Not always — the connection can be silently downgraded to HTTP"], "correct": 3, "explanation": "SSL stripping: an MITM attacker intercepts the unencrypted request before an HTTPS connection is established and substitutes https:// with http://. The victim sees the site without a padlock and doesn't notice. Protection: HSTS (HTTP Strict Transport Security) — the browser remembers that this domain is always HTTPS. But the first request is still vulnerable without a VPN." },
    { "id": 2, "difficulty": 2, "question": "Why is an Evil Twin attack so effective?", "options": ["Devices auto-join a familiar network name with a strong signal", "The attacker first cracks the real access point's password", "The attack exploits a WPA3 flaw to decrypt the traffic", "The victim sees a browser warning but usually ignores it"], "correct": 0, "explanation": "Devices remember network names (SSIDs) and automatically reconnect to familiar ones. Evil Twin uses the same SSID as the legitimate network but with a stronger signal — the device switches automatically. No password is needed for open networks. The victim receives no warnings. Disable 'auto-connect' in your Wi-Fi settings." },
    { "id": 3, "difficulty": 1, "question": "You urgently need to check your bank account while at a café. What is the safest approach?", "options": ["Join the cafe Wi-Fi — it has a password, so it's protected", "Open a private browser window, which hides your traffic", "Turn off Wi-Fi and use mobile data (4G/5G) instead", "Join the cafe Wi-Fi and open the banking app right away"], "correct": 2, "explanation": "Mobile data (4G/5G) is the safest option: other devices at the café have no access to it. A VPN on public Wi-Fi encrypts traffic but the Wi-Fi network itself remains a risk point. A Wi-Fi password doesn't protect you from traffic interception by other users on the same network. Incognito mode doesn't hide traffic — it only avoids saving browser history." },
    { "id": 4, "difficulty": 3, "question": "Why is WEP Wi-Fi encryption considered broken and dangerous?", "options": ["WEP uses outdated MD5, which is easy to decode", "WEP keys are too short and are guessed within hours", "Because of a weak IV, WEP keys are cracked in minutes", "WEP isn't supported by devices made after 2005"], "correct": 2, "explanation": "WEP uses RC4 with a 24-bit IV that periodically repeats. An attacker passively collects packets and statistically recovers the key. Tools like aircrack-ng crack WEP in 1–5 minutes with sufficient traffic. WEP was discredited as early as 2001. Use only WPA2 or WPA3." },
    { "id": 5, "difficulty": 1, "question": "What makes the 'auto-connect to Wi-Fi' feature on your phone dangerous?", "options": ["The phone drains faster from constantly scanning for networks", "The phone may join a fake or open network on its own", "The phone sends your home Wi-Fi password to nearby networks", "It's only risky for open networks; protected ones are safe"], "correct": 1, "explanation": "The phone stores a list of 'trusted' networks by SSID and automatically connects to any network with a matching name. 'Airport_WiFi' is easy to spoof. The device connects automatically and all traffic passes through the attacker. Disable auto-connect for all public networks and keep only your home Wi-Fi enabled." },
    { "id": 6, "difficulty": 1, "question": "Which encryption should you choose in your home router settings?", "options": ["WEP — the oldest and therefore proven option", "An open network with a hidden name (SSID)", "An open network with MAC address filtering", "WPA2 or WPA3 with a long unique password"], "correct": 3, "explanation": "WPA3 is the modern standard; WPA2 with a long password is also solid. WEP is cracked in minutes. A hidden network name and MAC filtering don't encrypt traffic: the name and allowed addresses are visible to anyone listening, and MAC addresses are easy to spoof." },
    { "id": 7, "difficulty": 2, "question": "Why change the router's default admin password (admin/admin)?", "options": ["Default passwords are public and appear in attack lists", "Otherwise the router will share the internet more slowly", "So neighbours can't see the name of your Wi-Fi network", "Without it the router won't receive firmware updates"], "correct": 0, "explanation": "Default passwords are published in manuals and collected into attack lists. In 2016 the Mirai botnet infected hundreds of thousands of cameras and routers simply by trying default logins. With admin access, an attacker can change DNS and quietly redirect you to phishing sites." },
    { "id": 8, "difficulty": 2, "question": "What does a VPN do on public Wi-Fi, and what does it NOT protect against?", "options": ["Makes you completely anonymous to all sites and services", "Encrypts traffic to the VPN server but doesn't stop phishing", "Protects against all viruses, phishing and malicious sites", "Encrypts only passwords; other traffic travels in the open"], "correct": 1, "explanation": "A VPN creates an encrypted tunnel from your device to its server, so the Wi-Fi owner and others on the network can't see your traffic. But a VPN doesn't check whether a site is honest: you'll type your password into a phishing page just the same. It doesn't make you anonymous to sites you're logged into and doesn't replace antivirus. The VPN provider itself sees your traffic, so choose a trustworthy one." },
  ],
  7: [
    { "id": 1, "difficulty": 2, "question": "Equifax didn't install an Apache Struts patch for two months and lost 147 million people's data. What conclusion is MOST accurate?", "options": ["Companies shouldn't use third-party libraries like Struts", "The breach was unavoidable: zero-days always get exploited", "The main problem was that Equifax had no antivirus", "Critical patches must go in fast: the hole is already attacked"], "correct": 3, "explanation": "CVE-2017-5638 was publicly known, and a fix was released in March 2017. The alert never reached the responsible developer, and Equifax's vulnerable portal wasn't updated. Attackers scan the internet for known flaws: according to Google Mandiant, in 2023 vulnerabilities were exploited on average 5 days after disclosure. You need a patch management process, not hope for 'later'." },
    { "id": 2, "difficulty": 1, "question": "What makes a zero-day vulnerability especially dangerous compared to a regular one?", "options": ["There's no patch for it from the vendor yet", "It's harder to write a working exploit for it", "It requires physical access to the device", "It only affects the very newest software versions"], "correct": 0, "explanation": "'Zero-day' means zero days of response time for the developer. With no patch, there's no technical defense. Antivirus misses it, firewalls don't block it — the vulnerability isn't documented yet. The only mitigations: least privilege principle, network segmentation, behavioral EDR systems. Zero-day exploits sell on the market for hundreds of thousands of dollars." },
    { "id": 3, "difficulty": 1, "question": "Your router vendor announces End-of-Life (EOL) — end of support. What does this mean in practice?", "options": ["The router will stop turning on within 30 days", "Internet speed will drop because of old firmware", "New vulnerabilities in it will never be fixed", "Only the device's warranty period is ending"], "correct": 2, "explanation": "EOL means: the vendor no longer releases patches. All vulnerabilities discovered after EOL will remain unpatched forever. A router with EOL firmware is a permanently widening hole in your home network's security. Replacing the device isn't an option — it's a necessity. The same applies to Windows XP, Android 8, and other EOL systems." },
    { "id": 4, "difficulty": 3, "question": "Why can Microsoft's 'Patch Tuesday' create risk?", "options": ["Microsoft deliberately slows computers down with updates", "Patches sometimes break things, so test them first", "Patches come out so often that IT teams can't read them", "Tuesday updates always require a reboot during work hours"], "correct": 1, "explanation": "The patching paradox in enterprise: major updates can break critical systems (ERP, medical equipment, industrial controllers). So organizations follow a patch management process: test in a staging environment → deploy in waves → monitor. The risk isn't in the updates themselves but in deploying them immediately without testing." },
    { "id": 5, "difficulty": 1, "question": "You see a pop-up: 'Update Java now!' with an 'Update' button. What is the safest action?", "options": ["Click 'Update' — updates must be installed immediately", "Check that the window has a Java logo, then update", "Click 'Remind me later' so the window stops bothering you", "Close the window and check for updates on java.com yourself"], "correct": 3, "explanation": "Pop-ups demanding you update Java, Flash, or your browser are a classic malware delivery method. Legitimate software updates through built-in mechanisms or official sites. Never click 'Update' in a browser pop-up window. Logos can be copied easily. Close the window and manually check for updates via Settings or the official site." },
    { "id": 6, "difficulty": 2, "question": "Your phone says a system update is ready to install. When is it best to install it?", "options": ["In six months, once everyone has found its bugs", "Never: updates only slow the phone down", "As soon as possible, at a convenient time within days", "Only when there's no space left for the old version"], "correct": 2, "explanation": "Updates fix vulnerabilities that attackers learn about once the patch is out: they study what was fixed and target people who haven't updated. For personal devices, install updates within a few days after backing up and charging. Turn on automatic updates if you're afraid you'll forget." },
    { "id": 7, "difficulty": 3, "question": "A supply chain attack is when:", "options": ["Hackers intercept a parcel with a new laptop in transit", "Malicious code arrives in an update of trusted software", "An attacker guesses the password to an online store's warehouse", "An employee sells the customer database to a competitor"], "correct": 1, "explanation": "In a supply chain attack, the attacker compromises the software vendor rather than the victim, and malicious code arrives in an official signed update. That's what happened with SolarWinds (2020, about 18,000 organizations) and 3CX (2023). Defenses: network segmentation, monitoring program behaviour and least privilege even for trusted software." },
    { "id": 8, "difficulty": 3, "question": "Why is it dangerous to turn off browser updates, even if nothing seems to change?", "options": ["Without updates the browser can't open HTTPS sites", "Browser updates only add new features and design", "An old browser version loads videos and photos slower", "Browser flaws let attackers strike just by visiting a site"], "correct": 3, "explanation": "A browser runs code from every site you open, so a vulnerability in it allows an attack simply by visiting a page (drive-by). Google and Mozilla regularly ship urgent updates for vulnerabilities that are already being exploited. Most patches don't change how the browser looks, but they close such holes." },
  ],
  8: [
    { "id": 1, "difficulty": 3, "question": "A company claims it 'anonymized' data by removing usernames. Why is this insufficient?", "options": ["Removing names is enough: a name is the only identifier", "People can be re-identified by age, location and purchases", "This is sufficient under GDPR for any kind of data", "This works for social media data, but not medical data"], "correct": 1, "explanation": "Latanya Sweeney's research (Carnegie Mellon University, 2000): knowing ZIP code, date of birth and gender is enough to identify 87% of Americans. Netflix 'anonymized' viewing data — researchers de-anonymized it by matching it with public IMDb ratings (Narayanan and Shmatikov, 2008). Real anonymization (k-anonymity, differential privacy) requires specialized methods, not just removing names." },
    { "id": 2, "difficulty": 3, "question": "What is browser fingerprinting and why is it hard to block?", "options": ["Saving passwords in the browser; it can be turned off in settings", "Identification via webcam; a camera cover blocks it", "An outdated technology replaced by localStorage", "Tracking by your browser's unique traits, without cookies"], "correct": 3, "explanation": "A browser fingerprint combines many parameters: browser and OS version, installed fonts, WebGL rendering, screen resolution, time zone. In the EFF Panopticlick study (2010), 84% of browsers were unique, and 94% of those with Flash or Java. Blocking cookies doesn't help here. Protection: Tor Browser (makes fingerprints identical), Firefox with resistFingerprinting. Fully blocking it is practically impossible." },
    { "id": 3, "difficulty": 2, "question": "The right to erasure (GDPR Art. 17) allows you to:", "options": ["Delete any information about yourself from any site in the world", "Force Google to remove any search results about you", "Ask a company to delete your data once it's no longer needed", "Get paid for a company's use of your personal data"], "correct": 2, "explanation": "The right to erasure is not absolute: a company can refuse if data is needed to fulfill a contract, for legal obligations, or for public interest. It applies only to companies handling EU residents' data. Google removes search results only from European versions of the search engine. Requests go to the DPA (supervisory authority) if the company refuses." },
    { "id": 4, "difficulty": 2, "question": "An app requests access to your microphone. What happens when you grant it?", "options": ["Depends on the OS: background recording may be possible", "The microphone works only while the app is on screen", "The permission applies only to calls inside the app", "iOS and Android completely forbid background recording"], "correct": 0, "explanation": "Since Android 9, background apps can't access the microphone, and modern iOS and Android show an indicator when it's on. But an app with permission can still record while it's open or running as a foreground service, and malware looks for workarounds. The principle: grant microphone access only to apps that truly need it (calls, voice messages), and choose 'only while using the app'." },
    { "id": 5, "difficulty": 1, "question": "Which browser setting provides the LEAST real protection against online tracking?", "options": ["Enabling the uBlock Origin extension", "Incognito / private browsing mode", "Using DNS over HTTPS (DoH)", "Disabling JavaScript on untrusted sites"], "correct": 1, "explanation": "Incognito mode only avoids saving history on your device. Your ISP, employer, and the sites you visit still see your traffic. Your IP address remains the same. Cookies aren't automatically blocked. Extensions like uBlock Origin, DoH, and JavaScript restrictions genuinely affect privacy. Incognito is protection from someone looking over your shoulder, not from tracking." },
    { "id": 6, "difficulty": 1, "question": "A notes app asks for access to your contacts and location. What's sensible?", "options": ["Deny: a notes app doesn't need this data", "Allow: otherwise it will work poorly", "Allow, and delete the app if anything happens", "Allow location but deny contacts"], "correct": 0, "explanation": "Give an app only the permissions its function needs. A notes app needs neither contacts nor location — such data is often collected for advertising. If an app won't work without extra permissions, that's a reason to find another one. You can review permissions in your phone settings at any time." },
    { "id": 7, "difficulty": 2, "question": "What is EXIF metadata in a photo?", "options": ["A watermark the social network adds to every photo", "Hidden details: time, camera and sometimes GPS location", "A filter that improves colours before posting", "A copy of the photo your phone keeps in the cloud"], "correct": 1, "explanation": "EXIF is data inside the photo file: phone model, date and time, camera settings and often GPS coordinates. Many social networks strip EXIF on upload, but messengers sending 'as a file', email and cloud links usually keep it. Before sending photos to strangers, remove location in the file properties or turn off geotagging in the camera." },
    { "id": 8, "difficulty": 3, "question": "A service says: 'We don't sell your data.' Why doesn't that mean your data goes nowhere?", "options": ["Selling data is illegal, so the phrase means nothing", "Data is only ever shared with law enforcement", "It means the service stores no data at all", "Data may be shared with partners and ad networks"], "correct": 3, "explanation": "'We don't sell' doesn't mean 'we don't share'. Data can go to 'partners', to ad networks through embedded trackers, to analytics services and contractors — formally that isn't a sale. What is shared and with whom is in the privacy policy, and data protection laws (Kazakhstan's Personal Data Law, the EU's GDPR) require disclosing it." },
  ],
  9: [
    { "id": 1, "difficulty": 1, "question": "You've discovered your email was hacked. What should you do FIRST?", "options": ["Warn all contacts not to open emails from you", "Delete the account and create a new mailbox", "Change the password and end all active sessions", "Only change the password; nothing else is needed"], "correct": 2, "explanation": "First regain control of the account: change the password and end all sessions — this blocks both new sign-ins and existing access (not every service kicks out other sessions automatically). Then enable 2FA and check forwarding rules and filters — attackers often add them to secretly receive copies of your mail. Warn your contacts after that. Don't delete the account: other accounts' recovery is tied to it." },
    { "id": 2, "difficulty": 2, "question": "Why do experts recommend NOT paying ransomware ransoms?", "options": ["It violates the attackers' copyright on their code", "Paying doesn't guarantee a key and funds new attacks", "Individuals technically can't pay in cryptocurrency", "The law in almost every country forbids paying ransom"], "correct": 1, "explanation": "Paying doesn't guarantee your data back: in a 2021 Sophos survey, organizations that paid recovered only 65% of their data on average, and just 8% got all of it back. Ransom funds new attacks, and those who pay get targeted again. The right approach: 3-2-1 backups, isolating infected systems, reporting to the police. Free decryptors for some ransomware exist at nomoreransom.org." },
    { "id": 3, "difficulty": 2, "question": "According to IBM (2025), companies take 181 days on average to identify a breach. What does this mean?", "options": ["Breaches are found 181 days after they've been fixed", "In 181 days hackers break into 181 systems on average", "181 days is the standard length of an investigation", "On average, attackers stay unnoticed for about half a year"], "correct": 3, "explanation": "181 days is the average time to identify a breach (IBM Cost of a Data Breach, 2025), with about 60 more days to contain it. All that time an attacker can study the infrastructure, expand access and exfiltrate data. Early detection is critical: the longer an attack goes unnoticed, the bigger the damage. That's why you need anomaly monitoring (SIEM), not just perimeter defense." },
    { "id": 4, "difficulty": 1, "question": "You notice three small charges of $1–5 from an unknown company on your card. What might this indicate?", "options": ["Fraudsters are testing a stolen card before a big theft", "It's an accidental subscription that's easy to cancel", "A technical glitch at the bank; the money will return", "The bank is making test charges to verify your card"], "correct": 0, "explanation": "Small 'test' transactions are a classic scheme: fraudsters check whether a stolen card works and whether fraud monitoring is active. If all is quiet, a large charge follows. Act immediately: block the card, report fraud to your bank, and request a chargeback. Don't wait — any delay increases the risk of major losses." },
    { "id": 5, "difficulty": 3, "question": "After discovering a breach, you want to reboot the infected computer. What might this destroy?", "options": ["Only temporary files in the %TEMP% folder", "Traces of the attack in RAM — evidence", "Nothing: all of the hacker's traces are on disk", "Only the files that were open during the attack"], "correct": 1, "explanation": "Digital forensics requires preserving the system state: a RAM image (RAM dump) can contain encryption keys, active malware processes, and network connections. Rebooting destroys this data permanently. In a serious incident: don't power off the device before a specialist arrives or before capturing a memory image (Volatility, FTK Imager)." },
    { "id": 6, "difficulty": 1, "question": "You followed a phishing link and entered your email password. What should you do right away?", "options": ["Wait: if nothing happens, everything is fine", "Delete the email and clear your browser history", "Run antivirus — it will cancel sending the password", "Change the password at once and turn on 2FA"], "correct": 3, "explanation": "The attacker already has your password, and it's a matter of minutes: stolen credentials are tested automatically almost immediately. Change the password (and everywhere you reused it), turn on 2FA, end other sessions and check email forwarding. Deleting the email or running antivirus won't take the stolen password back." },
    { "id": 7, "difficulty": 2, "question": "After your email was hacked you changed the password. Which setting do attackers often leave behind to keep reading your mail?", "options": ["A new dark colour theme for the mailbox interface", "Automatic forwarding to someone else's address", "A signature added to every outgoing message", "A filter that marks incoming emails as important"], "correct": 1, "explanation": "A forwarding rule keeps working after a password change: copies of every email, including recovery codes and bank notifications, keep going to the attacker. After a hack, check forwarding, filters, connected apps and backup emails and phone numbers in the security settings." },
    { "id": 8, "difficulty": 3, "question": "A company suffered a leak of customer data. Why is it important to notify those affected quickly and honestly?", "options": ["It only matters for reputation, not for security", "A notification automatically deletes the data from hackers", "People can change passwords and spot fraud in time", "After notifying, the company is no longer responsible"], "correct": 2, "explanation": "Victims can't protect themselves until they know about the leak: change passwords, block cards, watch for phishing that uses their data. That's why personal data laws (e.g. GDPR — 72 hours to notify the regulator) require reporting breaches. Hiding a breach increases the damage and the fines." },
  ],
  10: [
    { "id": 1, "difficulty": 1, "question": "The Principle of Least Privilege means:", "options": ["Users must never know the administrator password", "Only the least experienced staff get privileges", "Everyone has equal rights, to keep things fair", "Everyone gets only the rights their task needs"], "correct": 3, "explanation": "Least Privilege limits the blast radius of a compromise: a breached accountant's account shouldn't have access to source code. If malware runs under a regular user, it can't install a rootkit without admin rights. Applied to users, processes, services, and APIs. Violating this principle is one of the causes of large-scale breaches." },
    { "id": 2, "difficulty": 2, "question": "You used a strong, unique password and 2FA on a site. The site was hacked and the database published. What happened to your protection?", "options": ["You're completely exposed and must change passwords everywhere", "Password hashing and 2FA still protect your account", "After a database leak, 2FA stops protecting the account", "The attacker gets direct access; the password doesn't matter"], "correct": 1, "explanation": "If the site stored passwords correctly (bcrypt, Argon2 with salt), the attacker only got hashes — cracking them takes years or is impossible. A unique password prevents credential stuffing on other sites. 2FA requires physical access to the second factor. Conclusion: your account on that site is at risk, others are not. Still worth changing the password on that specific site." },
    { "id": 3, "difficulty": 3, "question": "What does the concept of 'Zero Trust Architecture' mean?", "options": ["Delete user accounts at the slightest suspicion", "Trust only open-source, never proprietary software", "Verify every access request, even inside the network", "Cut all external connections and work offline"], "correct": 2, "explanation": "Zero Trust abandons the 'perimeter' model where everything inside the network is considered safe. Under that model, a compromised VPN or an infected employee laptop gives the attacker broad access. In Zero Trust every request is verified regardless of where it comes from. Principles: explicit verification, least privilege, assume breach. Google has been using this approach (BeyondCorp) since the early 2010s." },
    { "id": 4, "difficulty": 2, "question": "Which combination of tools provides the MOST comprehensive account protection?", "options": ["Long unique password, FIDO2 key and a password manager", "Complex password, SMS codes and a good antivirus program", "Biometrics, a PIN code and an always-on VPN", "2FA, frequent password changes and incognito mode"], "correct": 0, "explanation": "A unique long password protects against credential stuffing and brute force. A password manager keeps passwords unique and complex without you having to remember them. A FIDO2 hardware key (like passkeys) resists phishing because it's bound to the domain. SMS is vulnerable to SIM swapping. Frequent password changes without a manager usually make passwords weaker. Antivirus and VPN matter, but they don't protect the account itself." },
    { "id": 5, "difficulty": 2, "question": "Your threat model should answer the question:", "options": ["Who might attack me, why, and what measures are proportionate", "How to defend against every possible attack at once", "Which antivirus ranks best in AV-TEST ratings", "How much full security costs and whether I can afford it"], "correct": 0, "explanation": "Threat modeling is individual risk assessment. A journalist protects sources from state actors. An entrepreneur protects financial data from fraudsters. A regular user protects against automated attacks and phishing. Different threats require different measures: paranoid protection everywhere is irrational, but no baseline protection is dangerous. Start with: 'Who am I interesting to and what can they do?'" },
    { "id": 6, "difficulty": 1, "question": "Which habit protects best against most attacks on accounts?", "options": ["Changing all passwords weekly to similar new ones", "Unique passwords in a manager and 2FA turned on", "Opening sites only in incognito mode", "Signing in only from a computer, never a phone"], "correct": 1, "explanation": "Most account takeovers come from reused passwords from leaks and from phishing. A unique password for every site defeats credential stuffing, and 2FA (preferably an app or a key) protects you even if the password is stolen. According to NIST guidance, frequent changes to similar passwords don't help, and incognito doesn't protect an account." },
    { "id": 7, "difficulty": 3, "question": "An email from the 'rector' asks you to urgently buy gift cards for partners and send the codes. Which attack signs are combined here?", "options": ["Only typos in the text and an odd font", "An attachment and a link to a third-party site", "The email arrived in the evening, not during work hours", "Urgency, authority and an unusual payment method"], "correct": 3, "explanation": "This is CEO fraud (business email compromise). Urgency stops you from thinking, the sender's authority suppresses doubt, and gift cards can't be traced or refunded. Such emails often have no links or attachments, so filters let them through. Verify by contacting the sender through a known channel." },
    { "id": 8, "difficulty": 3, "question": "What best describes the principle of 'defense in depth'?", "options": ["One most expensive security system instead of several", "Several independent layers, so one failure isn't fatal", "Protecting only the network perimeter; inside, trust everyone", "Regularly replacing all security tools with newer versions"], "correct": 1, "explanation": "Defense in depth builds several independent barriers: training people, email filtering, updates, antivirus, 2FA, backups. If a phishing email gets past the filter, a person may spot it; if a password is stolen, 2FA saves you; if ransomware encrypts everything, an offline backup does. No single measure is 100% reliable, so they are combined." },
  ],
};

